metadata.er-schema:
{
  "title": "looply · 物流信息服务 实体关系图",
  "version": "v2.3 · 2026-05-21",
  "tables": [
    {
      "name": "shipments",
      "comment": "运单",
      "columns": [
        {
          "name": "id",
          "comment": "运单ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "business_order_no",
          "comment": "业务单号（调用方传入）",
          "constraint": ""
        },
        {
          "name": "tracking_no",
          "comment": "运单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "carrier_id",
          "comment": "承运商",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "tracking_platform_id",
          "comment": "路由到的追踪平台",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "platform_status",
          "comment": "平台原始状态",
          "constraint": ""
        },
        {
          "name": "internal_status",
          "comment": "Looply内部状态",
          "constraint": ""
        },
        {
          "name": "notify_url",
          "comment": "状态回调地址",
          "constraint": ""
        },
        {
          "name": "source",
          "comment": "来源系统(业务系统标识)",
          "constraint": ""
        },
        {
          "name": "last_tracking_update",
          "comment": "最后轨迹更新时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "通过 API 注册，不关联具体订单实体"
    },
    {
      "name": "tracking_checkpoints",
      "comment": "轨迹节点",
      "columns": [
        {
          "name": "id",
          "comment": "节点ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "shipment_id",
          "comment": "关联运单",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "platform_tag",
          "comment": "平台一级状态(tag/state)",
          "constraint": ""
        },
        {
          "name": "platform_subtag",
          "comment": "平台二级状态(subtag/statusCode)",
          "constraint": ""
        },
        {
          "name": "message",
          "comment": "轨迹描述原文",
          "constraint": ""
        },
        {
          "name": "mapped_internal_status",
          "comment": "映射后Looply内部状态",
          "constraint": ""
        },
        {
          "name": "display_i18n_key",
          "comment": "映射后i18n key(国际段)",
          "constraint": ""
        },
        {
          "name": "location",
          "comment": "地点描述",
          "constraint": ""
        },
        {
          "name": "country_iso3",
          "comment": "国家代码",
          "constraint": ""
        },
        {
          "name": "checkpoint_time",
          "comment": "事件时间",
          "constraint": ""
        },
        {
          "name": "raw_payload",
          "comment": "原始JSON(用于排查)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": ""
    },
    {
      "name": "carriers",
      "comment": "承运商",
      "columns": [
        {
          "name": "id",
          "comment": "承运商ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name",
          "comment": "承运商名称",
          "constraint": "UNIQUE"
        },
        {
          "name": "code",
          "comment": "编码(如ups/sf-domestic)",
          "constraint": "UNIQUE"
        },
        {
          "name": "logo_url",
          "comment": "Logo地址",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态(启用/停用)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "同一物流公司如有国内外服务则拆成独立记录（如顺丰国内/顺丰国际）"
    },
    {
      "name": "tracking_platforms",
      "comment": "追踪平台",
      "columns": [
        {
          "name": "id",
          "comment": "平台ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name",
          "comment": "平台名称",
          "constraint": "UNIQUE"
        },
        {
          "name": "platform_type",
          "comment": "平台类型(国际聚合/国内聚合)",
          "constraint": ""
        },
        {
          "name": "api_key",
          "comment": "API Key（加密）",
          "constraint": ""
        },
        {
          "name": "webhook_secret",
          "comment": "Webhook密钥（加密）",
          "constraint": ""
        },
        {
          "name": "webhook_url",
          "comment": "Webhook回调地址",
          "constraint": ""
        },
        {
          "name": "connection_status",
          "comment": "连接状态(正常/异常)",
          "constraint": ""
        },
        {
          "name": "last_checked_at",
          "comment": "最后检测时间",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "如AfterShip(国际聚合)、快递100(国内聚合)"
    },
    {
      "name": "platform_carrier_mappings",
      "comment": "平台承运商映射",
      "columns": [
        {
          "name": "id",
          "comment": "映射ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "tracking_platform_id",
          "comment": "关联追踪平台",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "carrier_id",
          "comment": "关联Looply承运商",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "platform_carrier_code",
          "comment": "平台承运商代码",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "追踪平台↔Looply承运商的多对多映射"
    },
    {
      "name": "status_mappings",
      "comment": "状态映射",
      "columns": [
        {
          "name": "id",
          "comment": "映射ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "tracking_platform_id",
          "comment": "关联追踪平台",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "platform_status_code",
          "comment": "平台一级状态(tag/state)",
          "constraint": ""
        },
        {
          "name": "platform_status_meaning",
          "comment": "一级状态含义",
          "constraint": ""
        },
        {
          "name": "platform_sub_code",
          "comment": "平台二级状态(subtag/statusCode)",
          "constraint": ""
        },
        {
          "name": "platform_sub_meaning",
          "comment": "二级状态含义",
          "constraint": ""
        },
        {
          "name": "internal_status",
          "comment": "Looply内部状态",
          "constraint": ""
        },
        {
          "name": "display_i18n_key",
          "comment": "i18n key(国际平台用，对应subtag)",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "所有平台均可配置。每行对应一个subtag/statusCode级别映射，i18n key仅国际平台使用"
    },
    {
      "name": "message_logs",
      "comment": "消息记录",
      "columns": [
        {
          "name": "id",
          "comment": "消息ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "shipment_id",
          "comment": "关联运单",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "direction",
          "comment": "数据流向(inbound_api/outbound_platform/inbound_webhook/outbound_push)",
          "constraint": ""
        },
        {
          "name": "source",
          "comment": "来源方",
          "constraint": ""
        },
        {
          "name": "target",
          "comment": "目标方",
          "constraint": ""
        },
        {
          "name": "event",
          "comment": "事件名(registerTracking/createTracking/tracking_update/statusNotify)",
          "constraint": ""
        },
        {
          "name": "request_payload",
          "comment": "请求报文JSON",
          "constraint": ""
        },
        {
          "name": "response_payload",
          "comment": "响应报文JSON",
          "constraint": ""
        },
        {
          "name": "http_status",
          "comment": "HTTP状态码",
          "constraint": ""
        },
        {
          "name": "latency_ms",
          "comment": "响应耗时(ms)",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "处理状态(成功/失败)",
          "constraint": ""
        },
        {
          "name": "error_message",
          "comment": "错误信息",
          "constraint": ""
        },
        {
          "name": "triggered_by",
          "comment": "触发来源消息ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "记录四种数据流：业务系统请求/Looply请求物流平台/物流平台Webhook回调/推送业务系统消息"
    }
  ],
  "relations": [
    {
      "from": "shipments",
      "to": "tracking_checkpoints",
      "type": "1:N",
      "label": "轨迹节点",
      "color": "#1976D2"
    },
    {
      "from": "carriers",
      "to": "shipments",
      "type": "1:N",
      "label": "承运",
      "color": "#43A047"
    },
    {
      "from": "tracking_platforms",
      "to": "shipments",
      "type": "1:N",
      "label": "路由到平台",
      "color": "#43A047",
      "style": "dashed"
    },
    {
      "from": "tracking_platforms",
      "to": "platform_carrier_mappings",
      "type": "1:N",
      "label": "映射的承运商",
      "color": "#43A047"
    },
    {
      "from": "carriers",
      "to": "platform_carrier_mappings",
      "type": "1:N",
      "label": "在多平台的代码",
      "color": "#43A047"
    },
    {
      "from": "tracking_platforms",
      "to": "status_mappings",
      "type": "1:N",
      "label": "状态映射",
      "color": "#43A047"
    },
    {
      "from": "shipments",
      "to": "message_logs",
      "type": "1:N",
      "label": "消息记录",
      "color": "#8E24AA"
    },
    {
      "from": "message_logs",
      "to": "message_logs",
      "type": "1:N",
      "label": "触发(triggered_by)",
      "color": "#8E24AA",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "service_positioning": "系统定位为内部物流信息获取服务平台，为其他业务系统提供标准化物流信息查询服务。运单通过 API 注册，不直接关联订单实体",
    "unified_shipments": "shipments 统一管理国内/国际运单，不再区分。系统根据承运商→追踪平台映射自动路由到对应平台(AfterShip/快递100)",
    "carrier_split": "同一物流公司如同时有国内外服务则拆成独立承运商记录（如顺丰国内 sf-domestic / 顺丰国际 sf-international），不使用 scope 字段",
    "status_mapping_universal": "status_mappings 不再限制平台类型。每行对应一个 subtag/statusCode 级别映射。AfterShip 的 subtag 始终存在（无具体 subtag 时 fallback 到 _001 变体），因此只需一个 display_i18n_key 字段",
    "status_mapping_lookup": "查找顺序：先精确匹配 platform_status_code + platform_sub_code，匹配不到则 fallback 到仅 platform_status_code 的行",
    "i18n_optional": "display_i18n_key 仅国际平台(AfterShip)使用，对应 subtag 级别。国内平台(快递100)该字段为 NULL，前台轨迹文案直接使用原始 message 字段",
    "message_log_directions": "message_logs.direction 四种值：inbound_api(业务系统→Looply)、outbound_platform(Looply→物流平台)、inbound_webhook(物流平台→Looply)、outbound_push(Looply→业务系统)",
    "message_chain": "message_logs.triggered_by 建立消息因果链：业务系统请求 → 触发 Looply请求物流平台；物流平台Webhook回调 → 触发 推送业务系统消息",
    "checkpoint_mapping": "tracking_checkpoints 接收 Webhook 时立即完成状态映射，存储 mapped_internal_status。国际段额外存储 display_i18n_key，国内段该字段为 NULL",
    "encryption": "API Key/Secret 字段必须加密存储（AES-256）",
    "webhook_dedup": "tracking_checkpoints 通过联合唯一索引 (shipment_id, checkpoint_time, platform_tag, message) 去重",
    "platform_routing": "运单注册时根据 carrier_id → platform_carrier_mappings → tracking_platform_id 自动路由到对应追踪平台",
    "courier_redirect_link": "AfterShip 推送中包含 courier_redirect_link（承运商轨迹跳转链接），Looply 在状态通知中透传给业务系统，供用户端跳转查看承运商官方轨迹页面"
  }
}
